def loyalty_points(spend):
    if spend < 0:
        return {'status': 'error', 'points': 0}
    first_part = min(spend, 500.0)
    points_first = int(first_part // 10.0) * 1
    over = max(0.0, spend - 500.0)
    points_over = int(over // 10.0) * 2
    points = points_first + points_over
    if spend >= 1000.0:
        points += 50
    return {'status': 'ok', 'points': points}

